import ast,base64,json
sources=json.loads(base64.b64decode(""))
trees={k:ast.parse(v,filename=k) for k,v in sources.items()}
for k,t in trees.items():compile(t,k,"exec")
def dump(x):return ast.dump(x,include_attributes=False)
def funcs(t):return {n.name:n for n in t.body if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef))}
rows=[]
for prefix in ("full","comparison"):
 old,new=funcs(trees[prefix+"_old"]),funcs(trees[prefix+"_new"])
 unchanged=[k for k in old if k!="main" and dump(old[k])==dump(new[k])]
 assert len(unchanged)==len(old)-1
 first=new["main"].body[0]
 assert isinstance(first,ast.Expr) and isinstance(first.value,ast.Call) and isinstance(first.value.func,ast.Name) and first.value.func.id=="normal60_admission" and not first.value.args and not first.value.keywords
 assignments={n.targets[0].id:n.value for n in trees[prefix+"_new"].body if isinstance(n,ast.Assign) and len(n.targets)==1 and isinstance(n.targets[0],ast.Name)}
 assert ast.literal_eval(assignments["BINDING_READY"]) is False
 assert all(ast.literal_eval(assignments[x]) is None for x in ["NORMAL60_SHA","NORMAL_NATIVE_SHA","NORMAL_RELEASE_SHA","TRANSFER_SHA",("PIN" if prefix=="full" else "BINARY_SHA")])
 rows.append({"kind":prefix,"original_nonmain_definitions_byte_independent_ast_equal":unchanged,"first_main_statement_admission":True,"unbound_ready_false_and_five_pins_none":True})
a=funcs(trees["full_new"])["normal60_admission"];b=funcs(trees["comparison_new"])["normal60_admission"];assert dump(a)==dump(b)
loop=next(n for n in a.body if isinstance(n,ast.For));pairs=ast.literal_eval(loop.iter)
runnerassign={n.targets[0].id:n.value for n in trees["linux_runner"].body if isinstance(n,ast.Assign) and len(n.targets)==1 and isinstance(n.targets[0],ast.Name)}
assert pairs[0][0]=="ingress_observer_regression" and pairs[0][1]==list(ast.literal_eval(runnerassign["INGRESS_OBSERVER_TESTS"]))
assert pairs[1][0]=="cold_h2_regression" and pairs[1][1]==list(ast.literal_eval(runnerassign["COLD_H2_TESTS"]))
print(json.dumps({"schema":"heptabao.df026-x230-wrapper-source-peer-ast.v1","status":"passed","compiled_without_execution":list(trees),"rows":rows,"two_admission_definitions_equal":True,"runner_seven_and_nine_names_order_exact":True,"module_imported":False,"host_executed":False,"child_or_product_executed":False},sort_keys=True))
